declare -A F=( [src-261028-1euv]=toba [src-261028-e7xh]=yell [src-261028-o4u7]=snake [src-261028-0lka]=creede [src-261028-dtd8]=hook_a [src-261028-y8ny]=hook_b [src-261028-zu0b]=c5 [src-261028-013o]=c4 [src-261028-tfmg]=c3 [src-261028-tg02]=c2 [src-261028-w46k]=lead [src-261028-98ui]=end )
