r() { npm run -s cli -- rights:set "$1" approved_with_conditions --actor showrunner-planet-extremes --reason "$2" --evidence "$3" --condition "${COND[0]}" --condition "${COND[1]}" 2>&1 | tail -1; }
r src-261028-1euv "NASA EO Toba Caldera ASTER still (public domain), proposed by showrunner-planet-extremes" "https://earthobservatory.nasa.gov/images/7380/toba-caldera ; credit line: Image courtesy of NASA/GSFC/MITI/ERSDAC/JAROS, and the U.S./Japan ASTER Science Team. $EV_NASA"
